/* Buchee: ten discipline-specific teaching guides, not copied generic lesson paragraphs. */
(()=>{
'use strict';
const notes={"101 Hayvan":{"frame":["Hayvan bakımı bir kontrol listesine körü körüne uymak değildir; tür, yaş, ortam ve davranış aynı anda düşünülmelidir. Özellikle yeni bir değişiklik gözlendiğinde tek belirtiden kesin sonuç çıkarma.","Bir hayvanın güvenliğini değerlendirirken onun kendi hızını ve kaçınma işaretlerini dikkate al. İnsan için rahat görünen bir durum hayvan için stresli olabilir.","Günlük bakımda düzen kadar değişiklikleri fark etmek de önemlidir. Beslenme, hareket ve davranış kayıtları gerektiğinde veterinere anlaşılır bilgi sunar."],"interpret":["Olayı hayvanın bakış açısından değerlendir: bulunduğu yer güvenli mi, geri çekilebiliyor mu, zorlandığı bir an var mı? Müdahalenin acele olması bazen sorunu büyütür.","Bu örnekte önce gözlenebilen işareti, sonra olası açıklamayı ayır. Kesin tanı koymak yerine türün ihtiyacını ve destek gerekip gerekmediğini belirle.","Birden fazla neden aynı davranışa yol açabilir. Ortam koşullarını, son değişiklikleri ve hayvanın rahatlık düzeyini birlikte incelemek daha güvenilir bir başlangıçtır."],"method":["Hayvanın günlük rutinini not al, yeni bir uygulamaya geçmeden önce mevcut durumu gözlemle. Güvenli bir değişiklik yapacaksan küçük başla ve ters etki ortaya çıktığında dur.","Bakım kararını türüne uygun güvenilir kaynaklarla karşılaştır. Sağlık şüphesi, şiddetli korku veya belirgin davranış değişikliği varsa profesyonel değerlendirme önemlidir.","Ortamı güvenli kılmak çoğu zaman hayvanı zorla değiştirmeye çalışmaktan önce gelir. Erişim, ses, sıcaklık ve dinlenme alanlarını tek tek gözden geçir."],"risk":["Bir yöntemin başka bir hayvanda işe yaramış olması burada da uygun olduğunu kanıtlamaz. Özellikle sağlık, ilaç, beslenme ve davranış konularında rastgele müdahaleden kaçın.","Hayvanın sessiz kalmasını her zaman rahatlık sanma; korku ve rahatsızlık farklı işaretlerle görülebilir. Belirtiler sürüyorsa uzman görüşü almak gerekir.","Bakım rutinini sık sık ve aynı anda değiştirmek neyin etkili olduğunu anlamayı zorlaştırır. Değişiklikleri kayıt altına al ve güvenlik sınırlarını öncele."],"review":["Öğrendiğin en önemli nokta, hayvanın ihtiyaçlarını insan varsayımlarından ayrı değerlendirmektir. Bugünden itibaren hangi gözlemi daha düzenli yapacağını belirle.","Bu dersteki örneği kendi bakım ortamınla karşılaştır; hangi koşul farklı ve hangi adım güvenli uygulanabilir, not et.","Son değerlendirmede üç şeyi ayır: bildiğin bilgi, henüz gözlemlemediğin durum ve uzman yardımı gerektiren belirti."]},"101 Girişimcilik":{"frame":["Bir girişim fikri, çözümün ilginç olmasından çok gerçek bir ihtiyacı karşılamasıyla anlam kazanır. Kullanıcının bugün nasıl davrandığını öğrenmeden büyük kararlar vermek risklidir.","İlk hedef, çok özellik üretmek değil hangi sorunu çözmeye değer olduğunu anlamaktır. Kullanıcı sözleri ile tekrar eden davranışı birbirinden ayır.","Büyüme planını anlatırken varsayım, ölçülmüş veri ve hedefi aynı şey gibi gösterme. Bu ayrım daha erken ve daha az maliyetli karar aldırır."],"interpret":["Örnekte kim için hangi güçlük yaşanıyor, kullanıcı bugün hangi geçici çözümü kullanıyor ve bunu ne sıklıkla yapıyor sorularını ayır.","Olayın başında eldeki kanıtı belirle. Görüşmede beğenilen şey ile gerçek kullanım veya ödeme isteği arasında fark bulunabilir.","Bu senaryoda sürecin hangi adımında kayıp olduğunu düşün. Sorunun kaynağı ürün, erişim, güven veya zamanlama olabilir; tek ölçütle yetinme."],"method":["Küçük bir hipotez kur: hedef kullanıcı, beklenen davranış ve ölçüm yöntemi bir cümlede yer alsın. Test başlamadan başarı ölçütünü yaz.","Pahalı bir geliştirmeye başlamadan önce geri alınabilir bir deneme tasarla. Sonuçları kullanıcı segmentlerine göre incele ve belirsiz kalan noktaları açıkça belirt.","Ekipte bir kişinin sorumlu olduğu, başlangıç ve bitiş koşulları belli bir deneme seç. Öğrenilenleri sonraki karara dönüştürmek üretim hızından daha değerlidir."],"risk":["Arkadaşlarından gelen olumlu yorumları pazar doğrulaması saymak yanıltıcı olabilir. Gerçek kullanım, tekrar davranışı ve bağımsız geri bildirimi birlikte değerlendir.","Bir metrik yükseldiğinde diğer maliyetlerin de değişebileceğini unutma. Kullanıcı edinimi, destek ve hizmet maliyeti birlikte izlendiğinde karar güçlenir.","Küçük örneklemden büyük sonuç çıkarma; aynı denemenin farklı kitlelerde ne sonuç verebileceğini sınamadan ölçekleme kararı verme."],"review":["Bir sonraki adımın yeni özellik eklemek değil, belirsizliği azaltmak olabilir. Öğrendiğin veriyi ve hâlâ yanıtı olmayan soruyu yaz.","Dersin sonunda ölçebileceğin tek bir kullanıcı davranışı belirle. Hedefe ulaşılmazsa neyi değiştireceğini de önceden düşün.","Bu konuyu kurucunun gündelik kararına çevir: hangi varsayımı bırakıyor, hangi kanıtı topluyor ve neye göre ilerliyor?"]},"101 Finans":{"frame":["Finansal kararlar yalnızca en büyük görünen tutar üzerinden verilmez. Süre, toplam maliyet, nakde erişim ve kişisel koşullar sonucun parçasıdır.","Bir sayıyı yorumlamadan önce birimini, dönemini ve hangi giderleri kapsadığını kontrol et. Net ve brüt tutarların karıştırılması yaygın karar hatasıdır.","Bireysel finansın amacı her zaman en yüksek getiriyi seçmek değil, ihtiyaçlarla riskleri uyumlu yönetmektir. Önce paranın ne zaman gerekeceğini belirle."],"interpret":["Bu durumda para hangi tarihte geliyor, hangi tarihte çıkıyor ve elde kalması gereken güvenlik payı nedir sorularını sırala.","Örnekte birden fazla rakam varsa hangisinin gerçekleştiğini, hangisinin varsayım olduğunu ayır. Küçük görünen masraflar toplam kararı değiştirebilir.","Alternatifler arasında yalnızca oranları değil, toplam ödeme, vade, erişim koşulu ve beklenmedik durumları da karşılaştır."],"method":["Basit bir tablo oluştur: başlangıç tutarı, dönem, kesinti, toplam maliyet ve beklenen net sonuç. Bilinmeyen kalemleri sıfır varsayma.","İki senaryo karşılaştır: beklenen durum ile gelir ya da giderin değiştiği durum. Böylece tek tahmine bağımlı karar vermemiş olursun.","Bir maliyetin tek seferlik mi, düzenli mi ve değişken mi olduğunu işaretle. Karar verdikten sonra gerçekleşeni plana karşı kontrol et."],"risk":["Kesin kazanç vaatleriyle riskli ürünleri karıştırma. Finansal bilgi kişisel durumun yerine geçmez; gerektiğinde yetkili uzman ve güncel belgeye başvur.","Oranların aynı dönem ve aynı masraf kapsamıyla verildiğinden emin olmadan karşılaştırma yapma. Vergi ve işlem ücretleri net sonucu değiştirebilir.","Kısa vadeli yükümlülüğü karşılamak için gerekli parayı erişimi zor bir ürüne bağlamak risk doğurabilir. Likiditeyi gözden kaçırma."],"review":["Sonuçta tek bir soruya yanıt ver: bu karar bütçenin hangi kısmını etkiliyor ve kötü senaryoda nasıl ayakta kalır?","Öğrendiğin kavramı kendi aylık tablo veya hayali bir örnek üzerinde uygula. Hangi sayının bilinmediğini not et.","Bir sonraki finansal kararda karşılaştıracağın üç ölçütü açıkça yaz; değişen şartlarda bunları tekrar gözden geçir."]},"101 Teknoloji ve Yapay Zekâ":{"frame":["Bir dijital sistemin görünen ekranı, veri akışının yalnızca son parçasıdır. Kullanıcı isteği, işlem, veri saklama ve hata durumları bir bütün oluşturur.","Teknoloji terimini açıklamak için önce ne aldığına, ne ürettiğine ve hangi durumda hata verdiğine bak. Soyut tanımı çalışan bir örnekle ilişkilendir.","Bir otomasyonun doğru sonucu üretmesi kadar izlenebilir ve geri alınabilir olması da önemlidir. Özellikle kişisel veri söz konusu olduğunda yetki sınırı baştan düşünülmelidir."],"interpret":["Bu senaryoda girdinin kaynağını, hangi işlemden geçtiğini ve çıktının nasıl doğrulandığını ayrı ayrı incele.","Bir kullanıcı hatasıyla sistem hatasının aynı görünmesi mümkündür. Olayın hangi katmanda yaşandığını araştırmak çözümü hızlandırır.","Bu olayda güvenlik, performans ve kolay kullanım aynı anda düşünülmeli; yalnızca tek özelliği iyileştirmek diğerlerini etkileyebilir."],"method":["Önce beklenen davranışı yaz, ardından başarılı durum, yanlış giriş ve bağlantı kesintisi için ayrı test tasarla.","Veriyi doğrulayan küçük bir örnek oluştur. Girdi ve çıktı arasındaki ilişkiyi gözlemle; beklenmeyen sonucun nerede başladığını işaretle.","Bir özelliği canlıya almadan önce erişim yetkisini, hata mesajını ve geri alma yolunu kontrol et. Mümkünse değişikliği aşamalı dene."],"risk":["Tek bir deneme ya da gösterişli demo güvenilirlik kanıtı değildir. Gerçek kullanım verisini temsil eden testler ve sınır durumları gereklidir.","Kimlik doğrulanmış olması her veriye erişim hakkı vermez. Sunucu tarafındaki yetki ve gizlilik kontrolleri ayrı incelenmelidir.","Yapay zekâ tarafından akıcı üretilen metni doğrulanmış bilgiyle karıştırma. Hata olasılığı, kaynak ve kullanım amacı göz önünde tutulmalıdır."],"review":["Bir sonraki teknik adım için ölçülebilir bir test yaz. Hangi sonucun sistemin doğru çalıştığını göstereceğini açıkla.","Konuyu bir arkadaşına girdi, işlem, çıktı ve hata örneğiyle anlatabilecek duruma gelip gelmediğini kontrol et.","Bu dersin sonunda bir güvenlik sınırı, bir kullanıcı ihtiyacı ve bir ölçüm belirle; üçünü birlikte değerlendirmeyi alışkanlık hâline getir."]},"101 Sosyal Medya ve Pazarlama":{"frame":["İçerik yalnızca görünmek için değil, belirli bir insanın ihtiyacına karşılık vermek için hazırlanır. Etkileşimle gerçek hedefin aynı olmadığını unutma.","Her platformda aynı mesaj aynı biçimde çalışmayabilir. İçerik fikrini korurken sunumu kullanıcı bağlamına göre uyarlamak gerekir.","Markanın sesi tutarlı olmalı, fakat her paylaşımın hedefi açıkça belirlenmelidir. Keşfedilme, güven oluşturma ve dönüşüm farklı aşamalardır."],"interpret":["Bu örnekte kitle kim, içeriği hangi ihtiyaçla görüyor ve hangi adımın gerçekten değer ürettiğini ölçmek istiyorsun?","Kullanıcı davranışını yorumlarken gösterim sayısı, anlamlı etkileşim ve dönüşümü birbirinden ayır. Aynı sonuç her üç ölçütte görülmeyebilir.","Mesajı okuyan kişinin elindeki bilgi ile vermesi beklenen kararı birlikte düşün. Yanlış beklenti oluşturmak kısa vadeli ilgi sağlasa da güveni azaltabilir."],"method":["Önce tek bir amaç seç. Başlık, görsel, açıklama ve sonraki eylemin bu amaca hizmet edip etmediğini kontrol et.","Küçük bir içerik deneyi tasarla; değişen öğeyi tek tutarak iki sunumu benzer koşullarda karşılaştır.","Üretim sürecine açık kaynak kontrolü, yayın öncesi gözden geçirme ve yayın sonrası sonuç değerlendirmesi ekle."],"risk":["Yorumlarda görünen birkaç güçlü görüşü tüm kitlenin düşüncesi sayma. Sonuçların temsil gücünü değerlendir.","İddianın kaynağı belirsizse paylaşmadan önce doğrula; görünür düzeltme yapabilmek markanın güvenilirliğinin parçasıdır.","Sadece beğeni sayısına bakarak başarılı karar verme. Uzun vadeli kullanıcı güveni ve gerçek fayda metrikleri de önemlidir."],"review":["Bir sonraki içerik için hedef kitleyi, ana mesajı ve ölçmek istediğin tek davranışı yaz.","Bu konuya ait örneği başka bir formata çevirsen ana anlamı nerede koruman gerektiğini düşün.","Öğrenmeni üç kısa karara dönüştür: ne yayınlayacaksın, kime sunacaksın, başarısını nasıl anlayacaksın?"]},"101 Yazılım ve Tasarım":{"frame":["Bir arayüzün kalitesi ekran görüntüsünden çok kullanıcının görevini hatasız tamamlayabilmesiyle anlaşılır. Görsel düzen davranıştan ayrı değerlendirilemez.","Tasarım kararını verirken cihaz boyutunu, etkileşim biçimini ve erişilebilirliği aynı anda düşün. Tek bir ekran ölçüsü yeterli test değildir.","Çalışan bir ürünün görünüşü, hata durumları ve veri bütünlüğü kadar önemlidir. Kullanıcıya ne olduğunu anlatmayan bir arayüz güven kaybettirir."],"interpret":["Bu durumda kullanıcının amaçladığı eylemi ve takıldığı adımı ayrı kaydet. Sorunun yalnızca simgede mi, akışta mı olduğunu doğrula.","Bir ekranın boş, yükleniyor, hata ve başarılı durumlarını yan yana değerlendir. Kullanıcı yalnızca ideal durumu yaşamaz.","Dokunma alanı, kontrast, metin uzunluğu ve geri dönüş yolu gibi ayrıntıların görev üzerindeki etkisini somut testle ölç."],"method":["Gerçekçi bir görev seçip başlangıçtan sonuca kadar adımları çiz. Gereksiz karar noktalarını azaltıp tekrar dene.","Önce en küçük çalışan akışı oluştur, ardından mobil ve masaüstünde test et. Görünüm ile gerçek davranışın örtüştüğünü doğrula.","Bir değişikliği sürüm geçmişine kaydet; kırılan bir işlevin nerede başladığını gösterecek test ve geri alma yolu hazır tut."],"risk":["Görsel olarak kusursuz bir düzen, erişilemeyen butonu veya yanlış sonucu telafi etmez. Gerçek kullanıcı senaryosu ile kontrol et.","CSS düzeltmesini yeni bir ekranda sınamamak farklı boyutlarda taşmaya yol açabilir. Dar ekran, uzun metin ve klavye durumunu mutlaka dene.","Kullanıcı verisini yalnızca istemcide gizlemek yetmez; yetki ve veri erişim kuralları sunucu tarafında da uygulanmalı."],"review":["Bir ekran için başarı ölçütü belirle: kullanıcı görevi kaç adımda, hangi hata olmadan tamamlıyor?","Bu dersten tek bir kontrol maddesi seçip gerçek cihazda uygula. Gözleminle tasarım varsayımını karşılaştır.","Tasarımı değerlendirirken görünüm, işlev ve erişilebilirlik için ayrı sonuç kaydı tut."]},"101 Psikoloji ve İletişim":{"frame":["İletişimde gördüğün davranış ile o davranışa verdiğin anlam aynı şey değildir. Karşındaki kişinin deneyimini yalnızca tahmin ederek bildiğini sanma.","İyi bir konuşma, karşı tarafın sınırını ve kendi ihtiyacını aynı anda ciddiye alır. Bir cümle kurmadan önce amaç ve etkiyi düşün.","Duygu, düşünce ve gözlemi ayırabilmek anlaşmazlıkların büyümesini önler. Farklı açıklamalara açık kalmak önemli bir beceridir."],"interpret":["Bu durumda kimin ne söylediğini, ne gözlemlediğini ve ne hissettiğini ayrı yaz. Varsayım ile doğrudan duyulan sözü karıştırma.","Aynı olaya iki kişinin farklı anlam verebileceğini göz önüne al. Karşı tarafın niyetini kesin ilan etmek yerine doğrulayıcı bir soru hazırla.","Karşılıklı beklenti ve güven sınırlarını düşün. Bir mesajın yalnızca içeriği değil, zamanı ve bağlamı da etkili olabilir."],"method":["Suçlayıcı sıfatlar yerine gözlenen davranışı, sende bıraktığı etkiyi ve somut talebini ifade eden bir cümle dene.","Dinleme sırasında söyleneni kendi cümlelerinle özetleyip doğru anladığını sor. Yanlış anlaşılan kısmı birlikte düzelt.","Sakin bir konuşma alanı seç; karşındakine seçme ve yanıt verme hakkı tanı. Bir tarafın hazır olmaması da dikkate alınmalıdır."],"risk":["Bir insanın davranışını tek bir kişilik özelliğiyle açıklamak hatalı olabilir. Bağlamı ve doğrudan iletişimi öncele.","Bu eğitim tanı koyma veya terapi yerine geçmez. Sürekli zorlayıcı durumlarda güvenilir uzman desteğini değerlendirmek gerekir.","İkna adına baskı veya bilgi saklama kullanmak güveni zedeler. İzin ve kişisel sınırlar iletişim becerisinin parçasıdır."],"review":["Bu dersten sonra söylemek istediğin bir cümleyi daha açık, saygılı ve doğrulanabilir biçimde yeniden yaz.","Kendi tepkinle karşı tarafın davranışını ayırarak neyi değiştirebileceğini düşün.","Bir sonraki görüşmede hangi soruyu daha iyi soracağını ve hangi varsayımı kontrol edeceğini not et."]},"101 Kişisel Gelişim":{"frame":["İlerlemenin ölçüsü aynı anda çok şey yapmak değil, önemli bir işi sürdürülebilir biçimde ilerletmektir. Hedefin ilk adımı küçük ve görünür olmalı.","Alışkanlıkların çoğu yalnızca istek gücüyle değil, çevre ve tekrar eden işaretlerle sürer. Günlük koşulları gözlemlemek yararlıdır.","Kendini geliştirmek, her gün kusursuz performans istemek anlamına gelmez. Belirsizlik, dinlenme ve uyarlanabilir hedefler planın parçasıdır."],"interpret":["Bu durumun ne zaman yaşandığını, öncesindeki tetikleyiciyi ve ardından ne yaptığını ayrı yaz. Değişebilen küçük noktayı ara.","Engeli yalnızca motivasyon eksikliği diye adlandırma; zaman, kaynak, dikkat ve beklenti yükünü incele.","Hangi davranışın gerçekten hedefine yaklaştırdığını sor. Meşgul görünmekle anlamlı ilerleme sağlamak farklıdır."],"method":["Bir haftalık küçük deney seç: nerede, ne zaman, hangi davranışı yapacağını ve nasıl kaydedeceğini önceden belirle.","Hedefi gözlenebilir bir çıktıya böl. İlk adım başarılabilir değilse daha küçük bir parçaya dönüştür.","Düzeni kolaylaştırmak için çevrende tek bir değişiklik yap. Sonucu birkaç gün gözlemleyip işe yarayıp yaramadığını değerlendir."],"risk":["Bir günü kaçırmak ilerlemenin bittiği anlamına gelmez. Aşırı iddialı hedeflerin sürdürülemez hâle gelmesine dikkat et.","Başka birinin rutinini kendi koşullarına doğrudan kopyalamak faydasız olabilir. İhtiyacına ve kapasiteye göre ayarla.","Sürekli üretken olma baskısı dinlenme ve ilişkileri ihmal ettirebilir. Sağlıklı sınırları gözet."],"review":["Bugünden uygulayacağın bir adımı ve onu ne zaman gözden geçireceğini yaz.","Bu davranışın sana katkısını ölçebileceğin küçük bir işaret belirle. Süreci sonuç kadar izle.","Öğrendiğin yöntemi gereksizce büyütmeden yarın tekrar edebileceğin biçime indir."]},"101 Bilim ve Genel Kültür":{"frame":["Bilimsel açıklama, kulağa makul gelmesinden çok kanıt ve yöntemle sınanabilmesine dayanır. Bir iddianın hangi koşullarda geçerli olduğunu sor.","Kavramları anlamanın yolu yalnızca tanımları hatırlamak değildir; onları gözlenebilir bir olayla ilişkilendirmektir. Belirsizlik bilimin doğal parçasıdır.","Veri toplama yöntemi sonucu etkiler. Bir sayının nereden geldiğini bilmeden kesin bir açıklama yapmak doğru değildir."],"interpret":["Bu örnekte neyin doğrudan gözlendiğini, neyin yorum olduğunu ayır. İddianın yanlış çıkması hâlinde hangi verinin değişmesi gerektiğini düşün.","Olayı etkileyebilecek başka etkenleri listele. Tek gözlem, bir mekanizmayı kesin olarak ispatlamayabilir.","Ölçüm aracı, örneklem ve zaman ölçeğinin sonuca nasıl etki ettiğini değerlendir. Aynı verinin farklı sunuluşlarını karşılaştır."],"method":["Basit ve güvenli bir gözlem planı kur: neyi ölçüyor, hangi koşulları sabit tutuyor ve sonuçları nasıl kaydediyorsun?","Bir iddiayı güvenilir birincil kaynakla karşılaştır; yayın tarihi, yöntem ve sınırlamaları not et.","İki olası açıklama üret. Bunlardan hangisini ayıracak bir ölçüm yapılabileceğini yaz."],"risk":["İki şeyin birlikte görülmesi, birinin diğerine neden olduğunu tek başına kanıtlamaz. Karıştırıcı değişkenleri ara.","Ölçüm belirsizliğini yok saymak gerçekte olmayan bir kesinlik yaratabilir. Sonucun hangi sınırlarda yorumlanabileceğini belirt.","Tek bir çalışma tüm soruları kapatmaz. Bağımsız tekrarlar, yöntem kalitesi ve yeni kanıtlar değerlendirmeyi değiştirebilir."],"review":["Bu derste öğrendiğin kavramı bir gözlem ve bir belirsizlik ile açıklayabilecek misin?","Bir bilimsel iddia gördüğünde soracağın iki yöntembilim sorusunu not et.","Sonuçta bildiğin şey, tahmin ettiğin şey ve hâlâ test edilmesi gereken şey ayrı kalsın."]},"101 Kariyer ve İş Hayatı":{"frame":["İş hayatındaki gelişim yalnızca daha fazla görev almak değildir; beklenti, sorumluluk ve sonuçları açık hâle getirmektir.","Bir beceri hakkındaki iddiayı somut iş örneğiyle desteklemek güven sağlar. Emeği ve sonucu birbirine karıştırmadan anlat.","Profesyonel ilişkiler net iletişim, karşılıklı saygı ve sürdürülebilir sorumluluk gerektirir. Belirsiz anlaşmalar çoğu zaman yanlış beklentiye yol açar."],"interpret":["Bu örnekte senden beklenen sonuç nedir, kararı kim verecek ve hangi bilgi eksik sorularını ayrı yanıtla.","Görevi üstlenen kişiyle sonucu kullanan kişinin beklentileri aynı mı kontrol et. Teslimin ölçütünü açık konuş.","Bu olayda iletişim biçiminin zamanlama ve sorumluluk üzerindeki etkisini incele. Her sorun daha çok çalışmayla çözülmez."],"method":["Kısa bir iş planı yaz: hedef çıktı, sorumlu, bitiş tarihi ve kabul ölçütü açık olsun.","Bir başarı hikâyesini durum, senin yaptığın eylem ve gözlenen sonuç olarak üçe ayır.","Karşılıklı beklentiyi yazılı özetle; sonraki adımın kimde ve ne zaman olduğunu doğrula."],"risk":["Belirsiz görev kabul etmek sürekli ek iş yüküne dönüşebilir. Sorumluluk ile karar yetkisini birlikte netleştir.","Sadece çabayı anlatmak sonuç değerlendirmesinde eksik kalabilir. Ölçülebilir kanıt ve öğrenilenleri göster.","Sürekli ulaşılabilir olmayı profesyonellik sanmak sürdürülebilir değildir. İş ve kişisel yaşam sınırlarını koru."],"review":["Bir sonraki iş görüşmesi veya toplantısında soracağın netleştirici soruyu belirle.","Bu dersin becerisini gerçek bir iş çıktısında nasıl göstereceğini not et.","Bugünkü örneği kendi görevine uyarladığında hangi beklentiyi daha açık ifade edeceğini yaz."]}};
window.BucheeAcademyGuides={
 build(lesson,editor){
  const source=notes[lesson.cat];if(!source||!editor)return null;
  const n=Number(lesson.order||1)-1;
  const pick=(key,offset=0)=>source[key][(n+offset)%source[key].length];
  const principle=String(lesson.desc||'').trim().replace(/[.!?]+$/,'');
  const lessonName=String(lesson.name||'').trim();
  const h=editor.headings;
  return [
   {name:h[0],text:[principle+'. '+pick('frame')],task:''},
   {name:h[1],text:[pick('interpret',1)],example:editor.example,task:''},
   {name:h[2],text:[lessonName+' için somut yöntem: '+pick('method',2)],task:''},
   {name:h[3],text:[lessonName+' dersindeki yaklaşımı şimdi uygulamaya çevir. '+pick('method',1)],task:pick('review',2)},
   {name:h[4],text:[pick('risk',2)],task:''},
   {name:h[5],text:[''+lessonName+' konusunda bir sonraki kararda hangi bilgiyi kullanacağını belirle. '+pick('review')],task:''}
  ];
 }
};
})();